    {t="A", q=7861, n="Wanted: Vile Priestess Hexx and Her Minions", pn="Procura-se: Sacerdotisa Torpe Bagata e seus lacaios", lvl=51, xp=6100, npc="Call to Arms!", m=1425, x=79.08, y=78.99, f={"elite"}},
    {t="C", q=7861, n="Wanted: Vile Priestess Hexx and Her Minions", pn="Procura-se: Sacerdotisa Torpe Bagata e seus lacaios", lvl=51, xp=6100, m=1425, x=58.29, y=82.41, obj="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.  Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", pobj="Você recebeu ordens de matar a Sacerdotisa Torpe Bagata e 20 Guardas Aman'zasi Ramatorpe. Quando terminar, procure Primeva Presa-arrancada, na Aldeia Revatusco, que fica nas Terras Agrestes.  Você pode encontrar a Sacerdotisa Torpe Bagata e os Guardas Aman'zasi no alto de Jintha'Alor, nas Terras Agrestes.", f={"elite"}},
    {t="T", q=7861, n="Wanted: Vile Priestess Hexx and Her Minions", pn="Procura-se: Sacerdotisa Torpe Bagata e seus lacaios", lvl=51, xp=6100, npc="Primal Torntusk", pnpc="Primeva Presa-arrancada", m=1425, x=78.2, y=81.18, f={"elite"}},
